CREATE TYPE "MembershipStatus" AS ENUM ('INVITED', 'ACTIVE', 'SUSPENDED');
CREATE TABLE "users" ("id" UUID PRIMARY KEY, "email" VARCHAR(320) NOT NULL UNIQUE, "password_hash" VARCHAR(255), "display_name" VARCHAR(120), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL);
CREATE TABLE "tenants" ("id" UUID PRIMARY KEY, "name" VARCHAR(160) NOT NULL, "slug" VARCHAR(80) NOT NULL UNIQUE, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL);
CREATE TABLE "tenant_memberships" ("id" UUID PRIMARY KEY, "tenant_id" UUID NOT NULL, "user_id" UUID NOT NULL, "status" "MembershipStatus" NOT NULL DEFAULT 'INVITED', "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, CONSTRAINT "tenant_memberships_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE, CONSTRAINT "tenant_memberships_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "tenant_memberships_tenant_id_user_id_key" ON "tenant_memberships"("tenant_id", "user_id"); CREATE INDEX "tenant_memberships_user_id_idx" ON "tenant_memberships"("user_id");
CREATE TABLE "roles" ("id" UUID PRIMARY KEY, "tenant_id" UUID, "name" VARCHAR(80) NOT NULL, "description" VARCHAR(255), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(6) NOT NULL, CONSTRAINT "roles_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "roles_tenant_id_name_key" ON "roles"("tenant_id", "name"); CREATE INDEX "roles_tenant_id_idx" ON "roles"("tenant_id");
CREATE TABLE "permissions" ("id" UUID PRIMARY KEY, "key" VARCHAR(120) NOT NULL UNIQUE, "description" VARCHAR(255), "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "user_roles" ("user_id" UUID NOT NULL, "role_id" UUID NOT NULL, "assigned_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("user_id", "role_id"), CONSTRAINT "user_roles_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE, CONSTRAINT "user_roles_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE); CREATE INDEX "user_roles_role_id_idx" ON "user_roles"("role_id");
CREATE TABLE "role_permissions" ("role_id" UUID NOT NULL, "permission_id" UUID NOT NULL, PRIMARY KEY ("role_id", "permission_id"), CONSTRAINT "role_permissions_role_id_fkey" FOREIGN KEY ("role_id") REFERENCES "roles"("id") ON DELETE CASCADE, CONSTRAINT "role_permissions_permission_id_fkey" FOREIGN KEY ("permission_id") REFERENCES "permissions"("id") ON DELETE CASCADE); CREATE INDEX "role_permissions_permission_id_idx" ON "role_permissions"("permission_id");
CREATE TABLE "sessions" ("id" UUID PRIMARY KEY, "token_hash" VARCHAR(255) NOT NULL UNIQUE, "user_id" UUID NOT NULL, "tenant_id" UUID NOT NULL, "expires_at" TIMESTAMPTZ(6) NOT NULL, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "revoked_at" TIMESTAMPTZ(6), CONSTRAINT "sessions_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE, CONSTRAINT "sessions_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE); CREATE INDEX "sessions_user_id_expires_at_idx" ON "sessions"("user_id", "expires_at"); CREATE INDEX "sessions_tenant_id_idx" ON "sessions"("tenant_id");
CREATE TABLE "audit_logs" ("id" UUID PRIMARY KEY, "tenant_id" UUID NOT NULL, "actor_user_id" UUID, "request_id" VARCHAR(100) NOT NULL, "action" VARCHAR(120) NOT NULL, "resource_type" VARCHAR(120) NOT NULL, "resource_id" VARCHAR(120), "metadata" JSONB, "ip_address" INET, "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "audit_logs_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT, CONSTRAINT "audit_logs_actor_user_id_fkey" FOREIGN KEY ("actor_user_id") REFERENCES "users"("id") ON DELETE SET NULL); CREATE INDEX "audit_logs_tenant_id_created_at_idx" ON "audit_logs"("tenant_id", "created_at"); CREATE INDEX "audit_logs_actor_user_id_idx" ON "audit_logs"("actor_user_id"); CREATE INDEX "audit_logs_resource_type_resource_id_idx" ON "audit_logs"("resource_type", "resource_id");
